  '최근 7일 동안 끝난 업무가 없어요. 칠판에 업무를 등록하면 가동률과 효율이 여기에 쌓여요.': { zh: '最近 7 天没有完成的任务。在白板上登记任务后，运转率和效率会在这里累积。', ja: '直近7日間に終わったタスクがありません。ボードにタスクを登録すると、稼働率と効率がここに蓄積されます。', en: 'No tasks finished in the last 7 days. Add tasks on the board and utilization and efficiency will build up here.' },
  '최근 7일 완료 업무와 비용': { zh: '最近 7 天完成的任务与成本', ja: '直近7日間の完了タスクとコスト', en: 'Tasks done and cost, last 7 days' },
