  '평균 단계 시간': { zh: '平均步骤时间', ja: '平均段階時間', en: 'Avg step time' },
  '한도 사용': { zh: '上限使用', ja: '上限の使用', en: 'Limit used' },
  '한도·근무': { zh: '上限·考勤', ja: '上限・勤務', en: 'Limits and hours' },
  '회사 전체의 가동률과 효율을 분야별로 보고, 어디를 고치면 좋을지 짚어 줘요. 기간은 최근 7일이에요.': { zh: '按领域查看全公司的运转率和效率，并指出该改进的地方。统计期间为最近 7 天。', ja: '会社全体の稼働率と効率を分野別に確認し、どこを直せばよいかを示します。期間は直近7日間です。', en: 'Company-wide utilization and efficiency by area, with what to fix. Covers the last 7 days.' },
  // ── 업무 흐름 편집 ──
