  '앞으로': { zh: '往前', ja: '前へ', en: 'Earlier' },
  '반려되면 되돌리기': { zh: '被退回时返回', ja: '差し戻されたら戻す', en: 'Go back when sent back' },
  '조건이 맞으면 되돌리기': { zh: '满足条件时返回', ja: '条件が合えば戻す', en: 'Go back when the condition holds' },
