  'MCP {n}개가 지정돼 있어요. 바꾸려면 대표 계정으로 열어 주세요.': { zh: '已指定 {n} 个 MCP。要修改请用所有者账号打开。', ja: 'MCP が {n} 件指定されています。変更するにはオーナーのアカウントで開いてください。', en: '{n} MCP chosen. Open it as the owner to change them.' },
