  '{n}단계 · 작성 {count}개 동시 (비교 후 선택)': { zh: '第 {n} 步 · {count} 份撰写同时（比较后选择）', ja: '{n} 段階目 · 作成 {count} 件同時（比較して選択）', en: 'Stage {n} · {count} drafts at once (compare and pick)' },
