  '최대 {n}회': { zh: '最多 {n} 次', ja: '最大 {n} 回', en: 'up to {n}×' },
  '"{name}" 흐름을 지울까요?': { zh: '要删除“{name}”流程吗？', ja: '「{name}」フローを削除しますか？', en: 'Delete the “{name}” flow?' },
  '유형 기본 흐름 "{name}"을(를) 썼어요.': { zh: '使用了类型默认流程“{name}”。', ja: 'タイプ標準のフロー「{name}」を使いました。', en: 'Using the default “{name}” flow.' },
  '저장한 흐름 "{name}"을(를) 불러왔어요.': { zh: '已载入保存的流程“{name}”。', ja: '保存したフロー「{name}」を読み込みました。', en: 'Loaded the saved flow “{name}”.' },
  '추천 흐름 "{name}": {reason}': { zh: '推荐流程“{name}”：{reason}', ja: 'おすすめのフロー「{name}」：{reason}', en: 'Recommended flow “{name}”: {reason}' },
