  '{v}단계 반복 조건': { zh: '第 {v} 步重复条件', ja: '{v} 段階の繰り返し条件', en: 'Step {v} repeat condition' },
  '{v}단계 이름': { zh: '第 {v} 步名称', ja: '{v} 段階の名前', en: 'Step {v} name' },
  '{v}단계 최대 반복': { zh: '第 {v} 步最多重复', ja: '{v} 段階の最大繰り返し', en: 'Step {v} max repeats' },
  '{waiting}개 대기': { zh: '{waiting} 个等待', ja: '{waiting} 件待機', en: '{waiting} waiting' },
  '검수 기록 · {rounds}회 · 고친 지적 {fixed}건': { zh: '审核记录 · {rounds} 次 · 已修正 {fixed} 条', ja: 'チェック記録 · {rounds} 回 · 直した指摘 {fixed} 件', en: 'Review log · {rounds} rounds · {fixed} notes fixed' },
  '결제가 실패했어요. {n}일 안에 결제되지 않으면 개인 플랜으로 바뀌어요. 플랜을 다시 결제해 주세요.': { zh: '付款失败。如果 {n} 天内未付款，将变为个人套餐。请重新付款。', ja: '決済に失敗しました。{n}日以内に決済されなければパーソナルプランに変わります。もう一度決済してください。', en: 'Payment failed. Without payment within {n} days, you drop to the Personal plan. Please pay again.' },
  '근거 {n}곳': { zh: '依据 {n} 处', ja: '根拠 {n} か所', en: '{n} sources' },
  '내보내기 실패 ({status})': { zh: '导出失败（{status}）', ja: 'エクスポート失敗（{status}）', en: 'Export failed ({status})' },
  '다른 사무실 링크도 보기 (전체 {n}개)': { zh: '也显示其他办公室的链接（共 {n} 个）', ja: '他のオフィスのリンクも表示（全 {n} 件）', en: 'Show links for other offices too ({n} in all)' },
  '담당 업무 {assigned}개': { zh: '负责任务 {assigned} 个', ja: '担当タスク {assigned} 件', en: '{assigned} assigned' },
  '대기 {n}건': { zh: '等待 {n} 个', ja: '待機 {n} 件', en: '{n} waiting' },
  '대기 업무 {waiting}건': { zh: '排队任务 {waiting} 个', ja: '待機タスク {waiting} 件', en: '{waiting} queued tasks' },
  '대기열 +1: {v}': { zh: '队列 +1：{v}', ja: '待機列 +1：{v}', en: 'Queue +1: {v}' },
  '도구 {toolsCount}개 · 조사 때 자동 {auto}개 · 승인 후 실행 {approval}개': { zh: '{toolsCount} 个工具 · 调研时自动 {auto} 个 · 批准后执行 {approval} 个', ja: 'ツール {toolsCount} 個 · 調査時に自動 {auto} 個 · 承認後に実行 {approval} 個', en: '{toolsCount} tools · {auto} automatic in research · {approval} after approval' },
  '등록됨 {v} · 바꿀 때만 입력': { zh: '已登记 {v} · 仅在更换时输入', ja: '登録済み {v} · 変えるときだけ入力', en: 'Saved {v} · enter only to change' },
  '렌더링한 결과를 검수자가 보고 최대 {rounds}번까지 고쳐요. AI 호출이 2~4배 들어요.': { zh: '审核员会查看渲染结果，最多修改 {rounds} 次。AI 调用会增加 2~4 倍。', ja: 'レンダリングした結果をチェック担当が見て、最大 {rounds} 回まで直します。AI の呼び出しが2〜4倍かかります。', en: 'A reviewer checks the rendered result and fixes it up to {rounds} times. Uses 2–4× the AI calls.' },
  '보고서에 없는 숫자가 든 블록 {dropped}개는 뺐어요.': { zh: '已去掉 {dropped} 个含有报告中没有的数字的区块。', ja: 'レポートにない数字を含むブロック {dropped} 個は外しました。', en: 'Dropped {dropped} blocks with numbers not in the report.' },
  '비워 두면 "{v} 2" 같은 이름': { zh: '留空则命名为“{v} 2”之类', ja: '空欄なら「{v} 2」のような名前', en: 'Leave empty for a name like "{v} 2"' },
  '사람 기준 {hours}시간 = {money}': { zh: '按人工 {hours} 小时 = {money}', ja: '人なら {hours} 時間 = {money}', en: '{hours} h by a person = {money}' },
  '알아서 진행 ("{assumption}")': { zh: '自行推进（“{assumption}”）', ja: 'おまかせで進める（「{assumption}」）', en: 'Go ahead ("{assumption}")' },
  '업무 여정 · {flowSummary}': { zh: '任务流程 · {flowSummary}', ja: 'ワークフロー · {flowSummary}', en: 'Journey · {flowSummary}' },
  '연결됨 · 도구 {n}개': { zh: '已连接 · {n} 个工具', ja: '接続済み · ツール {n} 個', en: 'Connected · {n} tools' },
  '요청 실패 ({status})': { zh: '请求失败（{status}）', ja: 'リクエスト失敗（{status}）', en: 'Request failed ({status})' },
  '우리 프로젝트가 {n}% 완성됐어요': { zh: '我们的项目完成了 {n}%', ja: 'わたしたちのプロジェクトは {n}% 完成しました', en: 'Our project is {n}% complete' },
  '이익 {v}{v2}': { zh: '利润 {v}{v2}', ja: '利益 {v}{v2}', en: 'Profit {v}{v2}' },
  '일정이 몰린 날: {days} — 복지팀이 휴식을 먼저 챙겨요.': { zh: '日程密集的日子：{days} — 福利团队会先安排休息。', ja: '予定が詰まった日：{days} — 福利チームが休息を先に確保します。', en: 'Busy days: {days} — the welfare team puts rest first.' },
  '전체 진행률 {overall}%': { zh: '整体进度 {overall}%', ja: '全体の進捗率 {overall}%', en: 'Overall progress {overall}%' },
  '전체의 {n}%': { zh: '占全部的 {n}%', ja: '全体の {n}%', en: '{n}% of the whole' },
  '지금 권한으로는 {what}할 수 없어요.': { zh: '以当前权限无法{what}。', ja: '今の権限では{what}できません。', en: 'Your current permission doesn’t let you {what}.' },
  '지금 진행 중인 업무가 있어서 대기열 {v}번째로 들어가요. 앞 업무가 끝나면 자동으로 시작해요.': { zh: '当前有进行中的任务，将排在队列第 {v} 位。前面的任务结束后会自动开始。', ja: '進行中のタスクがあるので、待機列の {v} 番目に入ります。前のタスクが終わると自動で始まります。', en: 'A task is already running, so this goes in at number {v} in the queue and starts on its own after the one ahead.' },
  '지금은 {code}': { zh: '当前为 {code}', ja: '現在は {code}', en: 'Now {code}' },
  '진행 중: {v}': { zh: '进行中：{v}', ja: '進行中：{v}', en: 'In progress: {v}' },
  '진행률 {done}/{total}': { zh: '进度 {done}/{total}', ja: '進捗 {done}/{total}', en: 'Progress {done}/{total}' },
  '진행률 미분류 업무 {n}개': { zh: '未计入进度的任务 {n} 个', ja: '進捗未分類のタスク {n} 件', en: '{n} tasks not counted toward progress' },
  '첫 비밀번호 ({MIN_PASSWORD}자 이상)': { zh: '初始密码（{MIN_PASSWORD} 位以上）', ja: '初期パスワード（{MIN_PASSWORD} 文字以上）', en: 'First password ({MIN_PASSWORD}+ characters)' },
  '화면 검수 {rounds}회 뒤에도 남은 지적이 {issuesCount}건 있어요.': { zh: '经过 {rounds} 次画面审核后，仍有 {issuesCount} 条意见。', ja: '画面チェック {rounds} 回の後も残った指摘が {issuesCount} 件あります。', en: '{issuesCount} notes remain after {rounds} rounds of visual review.' },
  '화면 검수 {rounds}회 만에 통과했어요.': { zh: '经过 {rounds} 次画面审核后通过。', ja: '画面チェック {rounds} 回で通過しました。', en: 'Passed visual review in {rounds} rounds.' },
  '회사 월 예산 {budget} · 팀 상한 합계 {caps}': { zh: '公司月预算 {budget} · 团队上限合计 {caps}', ja: '会社の月予算 {budget} · チーム上限の合計 {caps}', en: 'Company monthly budget {budget} · team caps total {caps}' },
  '💼 {name} 손익 카드': { zh: '💼 {name} 损益卡片', ja: '💼 {name} の損益カード', en: '💼 {name} profit card' },
  '📊 호출 {calls}회 · 실패 {failures}회': { zh: '📊 调用 {calls} 次 · 失败 {failures} 次', ja: '📊 呼び出し {calls} 回 · 失敗 {failures} 回', en: '📊 {calls} calls · {failures} failures' },
