function lookup(source: string, language: Language) {
  const direct = CATALOGUE[source]?.[language];
  if (direct !== undefined) return direct;
  if (source.includes('{')) return undefined;
  // 이 문장에 {placeholder} 가 없으면 템플릿으로 저장돼 있어도 문장처럼 쓸 수 있다.
  // 빈 칸이 있으면 값을 채워야 하므로 t()로는 해석하지 않는다.
  const template = TEMPLATES[source]?.[language];
  // 번역 쪽에만 구멍이 남은 템플릿은 t()로 열면 {title} 이 그대로 보인다.
  // 그 문장은 tpl()로 불러야 한다.
  return template !== undefined && !template.includes('{') ? template : undefined;
}

function lookupTemplate(source: string, language: Language) {
  return TEMPLATES[source]?.[language];
}

/** Translates `ko` source text, falling back to the source itself when untranslated. */
export function translate(source: string, language: Language): string {
  return lookup(source, language) ?? source;
}

/**
 * Translates a sentence and fills its `{placeholders}`. Unknown placeholders are left
 * untouched so a missing variable is visible instead of silently blank.
 */
export function translateTemplate(source: string, language: Language, vars: Vars): string {
  const template = lookupTemplate(source, language) ?? source;
  return template.replace(PLACEHOLDER, (hole, key: string) => {
    const value = vars[key];
    return value === undefined || value === null ? hole : String(value);
  });
}

const regexEscape = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Translates a server/API message after its template values have already been filled. */
export function translateMessage(source: string, language: Language = active): string {
  if (language === 'ko') return source;
  const exact = SERVER_TEXT[source]?.[language] ?? lookup(source, language);
  if (exact !== undefined) return exact;
  for (const [key, translations] of [...Object.entries(TEMPLATES), ...Object.entries(SERVER_TEXT)]) {
    if (!key.includes('{') || !translations[language]) continue;
    const names: string[] = [];
    const pattern = regexEscape(key).replace(/\\\{(\w+)\\\}/g, (_hole, name: string) => {
      names.push(name);
      return '([\\s\\S]+?)';
    });
    const match = source.match(new RegExp(`^${pattern}$`));
    if (!match) continue;
    const vars = Object.fromEntries(names.map((name, index) => [name, match[index + 1]]));
    return translations[language]!.replace(PLACEHOLDER, (hole, name: string) => vars[name] ?? hole);
  }
  return source;
}

/**
 * Language for plain helper functions such as `eventLabel()`, which have no access to
 * React context. `LanguageProvider` sets this on every render.
 */
let active: Language = DEFAULT_LANGUAGE;

export const currentLanguage = () => active;

/** Idempotent: called during render, so repeated calls with the same value are harmless. */
export function setActiveLanguage(language: Language) {
  active = language;
}

/** Shorthand for `translate(src, active)`. */
export const t = (source: string) => translate(source, active);

/** Shorthand for `translateTemplate(src, active, vars)`. */
export const tpl = (source: string, vars: Vars) => translateTemplate(source, active, vars);

/** Formats a number in the active language's grouping conventions. */
export const num = (value: number) => value.toLocaleString(localeOf(active));

/**
 * Fixed sentences the server writes for the screen (staff lines, approval headlines) travel as their Korean source and
 * values between invisible marks, so each viewer reads them in their own screen language. AI output never does.
 */
const VIEWER_MARK = '⁣';
const VIEWER_TEXT = /⁣(\[[\s\S]*?\])⁣/g;

export function viewerText(source: string, vars: Vars = {}): string {
  // A value that is itself wrapped keeps its marks escaped inside the JSON, so the outer one still reads as one piece.
  return `${VIEWER_MARK}${JSON.stringify([source, vars]).replace(/⁣/g, '\\u2063')}${VIEWER_MARK}`;
}

function viewerSentence(source: string, language: Language): string {
  if (language === 'ko') return source;
  return SERVER_TEXT[source]?.[language] ?? lookupTemplate(source, language) ?? translate(source, language);
}

/** Puts every wrapped sentence in `text` into `language`; anything else is left as it is. */
export function localize(text: string, language: Language = active): string {
  if (!text.includes(VIEWER_MARK)) return text;
  return text.replace(VIEWER_TEXT, (whole, json: string) => {
    try {
      const [source, vars] = JSON.parse(json) as [string, Vars];
      return viewerSentence(source, language).replace(PLACEHOLDER, (hole, key: string) => {
        const value = vars[key];
        if (value === undefined || value === null) return hole;
        // Step names and categories are fixed words too; titles and AI text are not in the catalogue and stay as they are.
        return typeof value === 'string' ? viewerSentence(localize(value, language), language) : String(value);
      });
    } catch {
      return whole;
    }
  });
}
